/* NANO POS 1.0.90: secondary desktop login; fail closed when host is unavailable. */
(function(){
'use strict';
if(window.__nanoSecondaryLogin190)return;window.__nanoSecondaryLogin190=true;
const $=id=>document.getElementById(id),S={mode:'main',busy:false,bypass:false};
const t={
ar:{main:'دخول عادي (كمبيوتر رئيسي / مستقل)',other:'الدخول ككمبيوتر ثانوي',ip:'IP الكمبيوتر الرئيسي (LAN أو Tailscale)',code:'رمز الاقتران (6 أرقام)',name:'اسم هذا الكمبيوتر',test:'اختبار الاتصال',ready:'الاتصال ناجح',working:'جاري الاتصال بالكمبيوتر الرئيسي ومزامنة البيانات…',bad:'الكمبيوتر الرئيسي غير متصل. تم منع الدخول ببيانات محلية.',codeNeeded:'أدخل رمز الاقتران المكوّن من 6 أرقام من الكمبيوتر الرئيسي.',ipNeeded:'أدخل عنوان IP للكمبيوتر الرئيسي.',native:'يعمل خيار الكمبيوتر الثانوي من تطبيق Windows المثبت فقط.',host:'هذا الكمبيوتر مضبوط كرئيسي بالفعل. لا يمكن تحويله إلى ثانوي من صفحة الدخول.',paired:'هذا الكمبيوتر مرتبط مسبقًا. اختر الدخول الثانوي أو افصل الربط من الإعدادات.',snapshot:'لم تصل بيانات الكمبيوتر الرئيسي بعد. أعد المحاولة.',help:'فعّل وضع الكمبيوتر الرئيسي من الإعدادات في الجهاز الأساسي. المنفذ الافتراضي 4178، ولا حاجة إلى إعادة إدخال رمز الاقتران إذا كان الجهاز مرتبطًا سابقًا.'},
fr:{main:'Connexion normale (PC principal / autonome)',other:'Connexion comme PC secondaire',ip:'IP du PC principal (LAN / Tailscale)',code:'Code de liaison (6 chiffres)',name:'Nom du PC secondaire',test:'Tester la connexion',ready:'Connexion réussie',working:'Connexion et synchronisation avec le PC principal…',bad:'PC principal inaccessible. Connexion locale bloquée.',codeNeeded:'Saisissez le code de liaison à 6 chiffres.',ipNeeded:'Saisissez l’adresse IP du PC principal.',native:'Cette fonction exige NANO POS installé sur Windows.',host:'Cet ordinateur est configuré comme principal.',paired:'Cet appareil est déjà lié. Choisissez le mode secondaire ou dissociez-le dans les paramètres.',snapshot:'Les données du PC principal ne sont pas reçues.',help:'Activez le mode principal sur le PC central (port 4178). Le code peut être réutilisé pour une liaison enregistrée.'},
en:{main:'Normal login (main / standalone PC)',other:'Sign in as secondary PC',ip:'Main PC IP (LAN or Tailscale)',code:'Pairing code (6 digits)',name:'Secondary computer name',test:'Test connection',ready:'Connection successful',working:'Connecting to main PC and syncing data…',bad:'Main PC unavailable. Local login blocked.',codeNeeded:'Enter the 6-digit pairing code.',ipNeeded:'Enter the main PC IP address.',native:'This mode requires NANO POS installed on Windows.',host:'This computer is currently configured as the main PC.',paired:'Already linked. Choose secondary login or disconnect in settings.',snapshot:'Primary PC data was not received.',help:'Enable host mode on the main PC (port 4178). A saved pairing can be reused without entering the code.'}};
const tr=()=>t[document.documentElement.lang]||t.ar;
const api=()=>window.nanoNative;
const host=()=>String($('nanoLoginHost')?.value||'').trim();
function message(v,ok=false){const e=$('nanoSecondaryStatus');if(e){e.hidden=!v;e.textContent=v||'';e.style.color=ok?'#167e49':'#bb2d2d';}}
function relabel(){const m=tr();for(const [id,k] of [['nanoLoginMainLabel','main'],['nanoLoginSecondaryLabel','other'],['nanoLoginHostLabel','ip'],['nanoLoginCodeLabel','code'],['nanoLoginNameLabel','name'],['nanoLoginTest','test'],['nanoLoginHelp','help']]){const e=$(id);if(e)e.textContent=m[k];}}
function mode(which){S.mode=which==='secondary'?'secondary':'main';$('nanoSecondaryFields').hidden=S.mode!=='secondary';$('nanoLoginAsMain').checked=S.mode==='main';$('nanoLoginAsSecondary').checked=S.mode==='secondary';message('');relabel();}
function snapshot(){let timer,settled=false;let end;const promise=new Promise(resolve=>end=resolve);const handler=()=>{if(settled)return;settled=true;clearTimeout(timer);window.removeEventListener('nano-pc-sync-snapshot-applied',handler);end(true);};window.addEventListener('nano-pc-sync-snapshot-applied',handler,{once:true});timer=setTimeout(()=>{if(settled)return;settled=true;window.removeEventListener('nano-pc-sync-snapshot-applied',handler);end(false);},10000);return{promise,cancel(){if(!settled){settled=true;clearTimeout(timer);window.removeEventListener('nano-pc-sync-snapshot-applied',handler);end(false);}}};}
async function test(){if(!api()?.testPcSyncConnection)throw Error(tr().native);if(!host())throw Error(tr().ipNeeded);const ping=await api().testPcSyncConnection({host:host()});if(!ping?.success)throw Error(ping?.message||tr().bad);if(ping.mode!=='host')throw Error('هذا الجهاز لا يعمل بوضع الكمبيوتر الرئيسي.');return ping;}
async function connect(){const n=api();if(!n?.getPcSyncInfo||!n?.pcSyncNow||!n?.joinPcSync)throw Error(tr().native);const before=await n.getPcSyncInfo();if(before?.mode==='host')throw Error(tr().host);await test();const wait=snapshot();try{let result;if(before?.mode==='client'&&before.host===host()){result=await n.pcSyncNow();}else{const code=String($('nanoLoginJoinCode')?.value||'').trim();if(!/^\d{6}$/.test(code))throw Error(tr().codeNeeded);result=await n.joinPcSync({host:host(),code,name:String($('nanoLoginDeviceName')?.value||'').trim()});}
if(!result?.success)throw Error(result?.message||result?.error||tr().bad);
if(!(await wait.promise))throw Error(tr().snapshot);
const after=await n.getPcSyncInfo();if(after?.mode!=='client'||!after.connected||after.host!==host())throw Error(tr().bad);
try{localStorage.setItem('nano-login-pc-host-v190',host());}catch{}return true;}finally{wait.cancel();}}
async function submit(event){if(event.target!==$('loginForm'))return;if(S.bypass){S.bypass=false;return;}event.preventDefault();event.stopImmediatePropagation();if(S.busy)return;S.busy=true;const btn=$('loginBtn');if(btn)btn.disabled=true;
try{const info=await api()?.getPcSyncInfo?.();if(S.mode==='secondary'){message(tr().working,true);await connect();message(tr().ready,true);}else if(info?.mode==='client')throw Error(tr().paired);
S.bypass=true;$('loginForm').requestSubmit();S.bypass=false;}catch(e){S.bypass=false;message(e?.message||tr().bad);}finally{S.busy=false;if(btn)btn.disabled=false;}}
async function init(){const form=$('loginForm');if(!form||$('nanoLoginPcRoles'))return;
const style=document.createElement('style');style.textContent='#nanoLoginPcRoles{margin:12px 0 14px;text-align:start;font-size:12px}.nano-pc-modes{display:grid;grid-template-columns:1fr 1fr;gap:8px}.nano-pc-modes label{display:flex;align-items:center;gap:5px;background:#ecf5ff;border:1px solid #bdd6f2;border-radius:10px;color:#174b8c;padding:9px;cursor:pointer;font-weight:700}.nano-pc-modes input{accent-color:#2563eb}#nanoSecondaryFields{padding:12px;margin:8px 0;background:#f3f8ff;border:1px solid #bfdbfe;border-radius:12px}#nanoSecondaryFields[hidden]{display:none!important}#nanoSecondaryFields label{display:block;margin:7px 0 4px;font-weight:700}#nanoSecondaryFields input{width:100%;height:39px;box-sizing:border-box;background:#fff;border:1px solid #bdcddd;border-radius:9px;color:#112244;padding:7px 10px;font:inherit}#nanoLoginTest{margin:10px 0;border:1px solid #9bc6f3;background:#deefff;color:#1a5597;padding:8px 13px;border-radius:9px;font-weight:800;cursor:pointer}#nanoLoginHelp,#nanoSecondaryStatus{font-size:11px;line-height:1.6}#nanoLoginHelp{color:#526b80}#nanoSecondaryStatus{font-weight:700}';document.head.append(style);
const block=document.createElement('div');block.id='nanoLoginPcRoles';block.innerHTML='<div class="nano-pc-modes"><label><input type="radio" id="nanoLoginAsMain" name="nanoLoginPcMode" checked><span id="nanoLoginMainLabel"></span></label><label><input type="radio" id="nanoLoginAsSecondary" name="nanoLoginPcMode"><span id="nanoLoginSecondaryLabel"></span></label></div><div id="nanoSecondaryFields" hidden><label for="nanoLoginHost" id="nanoLoginHostLabel"></label><input id="nanoLoginHost" type="text" autocomplete="off" dir="ltr" placeholder="192.168.1.20 / 100.80.20.10"><label id="nanoLoginCodeLabel" for="nanoLoginJoinCode"></label><input id="nanoLoginJoinCode" type="text" autocomplete="off" inputmode="numeric" maxlength="6" dir="ltr" placeholder="••••••"><label id="nanoLoginNameLabel" for="nanoLoginDeviceName"></label><input type="text" id="nanoLoginDeviceName" maxlength="80" autocomplete="off" placeholder="NANO PC 2"><button type="button" id="nanoLoginTest"></button><p id="nanoLoginHelp"></p><p id="nanoSecondaryStatus" role="status" aria-live="polite" hidden></p></div>';
form.insertBefore(block,$('loginBtn'));$('nanoLoginAsMain').addEventListener('change',()=>mode('main'));$('nanoLoginAsSecondary').addEventListener('change',()=>mode('secondary'));
$('nanoLoginTest').addEventListener('click',async()=>{if(S.busy)return;S.busy=true;try{await test();message(tr().ready,true);}catch(e){message(e?.message||tr().bad);}finally{S.busy=false;}});
document.addEventListener('submit',submit,true);let info;try{info=await api()?.getPcSyncInfo?.();}catch{}
try{$('nanoLoginHost').value=info?.host||localStorage.getItem('nano-login-pc-host-v190')||'';}catch{}
mode(info?.mode==='client'?'secondary':'main');
new MutationObserver(relabel).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();